def tweak(source: str, old: str, new: str, tag: str, actions: list[str]) -> str:
    if new in source:
        return source
    n = source.count(old)
    if n == 1:
        actions.append(tag)
        return source.replace(old, new, 1)
    if n > 1:
        # No guessing when unrelated effects share the same string.
        print('  skip ambiguous visual target:', tag, f'({n} matches)')
    return source


def fix_fx(source: str) -> tuple[str, list[str]]:
    actions: list[str] = []
    if 'zephyrSwitchFlourish' not in source or 'dragon_switch_' not in source:
        raise RuntimeError('Zephyr V20+ switch logic not found in src/game/game.ts; cannot safely patch.')

    # Specific colored ring earned on a clean F-switch hit. Its whitespace and
    # surrounding block vary across V20-V22 versions; match only this effect.
    color_ring = re.compile(
        r'(?m)^(?P<indent>[ \t]*)this\.fxp\(\s*"ring"\s*,\s*d\.chest\(\)\s*,\s*"#a9ffe6"\s*,\s*\.65\s*,\s*\.14\s*,\s*\.55\s*\);[ \t]*$'
    )
    if color_ring.search(source):
        source, n = color_ring.subn(lambda m: m.group('indent') + '// ' + MARK + ': F-switch colored ring removed.', source)
        actions.append(f'removed switch-hit turquoise ring ({n})')

    # Keep the rest of the Rhythm messages unchanged, but make the F-switch
    # notification white instead of mint.
    source=tweak(source,
        '`HIDDEN RHYTHM ${attacker.dragonRhythm}/3`,"#b7ffe3",.72);',
        '`HIDDEN RHYTHM ${attacker.dragonRhythm}/3`,\n        a.style === "zephyr_switch" ? "#ffffff" : "#b7ffe3",.72);',
        'neutral switch Rhythm label',actions)

    # The normal hit renderer uses the hero's custom green glow unless the
    # attack is explicitly recognized as a Zephyr F switch. Restrict to only
    # those attacks; ordinary Zephyr and all other heroes keep their FX.
    if 'const neutralDragonSwitch' not in source:
        glow = re.compile(
            r'const glow\s*=\s*attacker\s+instanceof\s+Fighter\s*\?\s*attacker\.look\.glow\s*:\s*attacker\s+instanceof\s+Mob\s*\?\s*attacker\.def\.color\s*:\s*"#ffffff"\s*;'
        )
        replacement=('// '+MARK+': neutralize *only* real F-switch hit effects.\n'
                     '    const neutralDragonSwitch = attacker instanceof Fighter &&\n'
                     '      attacker.kit === "tristaff" && (a.style === "zephyr_switch" || a.id.startsWith("dragon_switch_"));\n'
                     '    const glow = neutralDragonSwitch ? "#dedede" :\n'
                     '      attacker instanceof Fighter ? attacker.look.glow :\n'
                     '      attacker instanceof Mob ? attacker.def.color : "#ffffff";')
        source,n=glow.subn(lambda m:replacement,source,count=1)
        if n!=1:
            raise RuntimeError('Cannot find the shared hit-glow statement. No files changed; send src/game/game.ts for a custom patch.')
        actions.append('isolated neutral gray switch hit glow')

    source=tweak(source,
        '        if (attacker instanceof Fighter) this.highlightHit(attacker, a, d.lastDamage, result === "ko");',
        '        if (attacker instanceof Fighter && !neutralDragonSwitch)\n          this.highlightHit(attacker, a, d.lastDamage, result === "ko");',
        'suppressed colored switch highlight',actions)

    # Additional contact/sparring effects. Only replace recognized exact
    # generic calls to avoid applying colors to unrelated animations.
    changes=(
      ('this.fxp("sparks", hitPos, "#fff4d4", heavy ? 18 : 10, 6);',
       'this.fxp("sparks", hitPos, neutralDragonSwitch ? "#e7e7e7" : "#fff4d4", neutralDragonSwitch ? 6 : heavy ? 18 : 10, 6);', 'gray spark contacts'),
      ('this.fxp("impactBurst", shieldPos, "#ffe19c", 0.76, "block");',
       'this.fxp("impactBurst", shieldPos, neutralDragonSwitch ? "#dedede" : "#ffe19c", 0.76, "block");', 'gray blocked impact'),
      ('this.fxp("clashBurst", shieldPos, "#ffd27a", 0.72);',
       'this.fxp("clashBurst", shieldPos, neutralDragonSwitch ? "#dedede" : "#ffd27a", 0.72);', 'gray block clash'),
      ('this.fxp("sparks", shieldPos, "#ffd27a", 16, 5, dir.clone().negate().add(new THREE.Vector3(0, 0.3, 0)));',
       'this.fxp("sparks", shieldPos, neutralDragonSwitch ? "#dedede" : "#ffd27a", 16, 5, dir.clone().negate().add(new THREE.Vector3(0, 0.3, 0)));', 'gray blocked sparks'),
      ('this.fxp("flash", shieldPos, "#ffd980", 0.35, 0.1, 0.6);',
       'this.fxp("flash", shieldPos, neutralDragonSwitch ? "#ffffff" : "#ffd980", neutralDragonSwitch ? 0.11 : 0.35, 0.1, 0.6);', 'gray block flash'),
      ('this.fxp("impactBurst", shieldPos, "#b9f5ff", 1.65, "clash");',
       'this.fxp("impactBurst", shieldPos, neutralDragonSwitch ? "#dedede" : "#b9f5ff", 1.65, "clash");', 'gray parry impact'),
      ('this.fxp("impactFrame", "parry", "#b9f5ff", 0.72);',
       'this.fxp("impactFrame", "parry", neutralDragonSwitch ? "#dedede" : "#b9f5ff", 0.72);', 'gray parry frame'),
      ('this.fxp("clashBurst", shieldPos, "#aee9ff", 1.15);',
       'this.fxp("clashBurst", shieldPos, neutralDragonSwitch ? "#dedede" : "#aee9ff", 1.15);', 'gray parry clash'),
      ('this.fxp("sparks", shieldPos, "#aee9ff", 40, 9);',
       'this.fxp("sparks", shieldPos, neutralDragonSwitch ? "#dedede" : "#aee9ff", 40, 9);', 'gray parry sparks'),
      ('this.fxp("flash", shieldPos, "#b3f2ff", 0.5, 0.2, 0.9);',
       'this.fxp("flash", shieldPos, neutralDragonSwitch ? "#ffffff" : "#b3f2ff", neutralDragonSwitch ? 0.12 : 0.5, 0.2, 0.9);', 'gray parry flash'),
      ('this.fxp("ring", shieldPos, "#b3f2ff", 0.8, 0.35, 0.9);',
       'this.fxp("ring", shieldPos, neutralDragonSwitch ? "#dedede" : "#b3f2ff", 0.8, 0.35, 0.9);', 'gray parry ring'),
      ('this.fxp("num", shieldPos.clone().add(new THREE.Vector3(0, 0.5, 0)), "PARRY!", "#8fe6ff", 1.4);',
       'this.fxp("num", shieldPos.clone().add(new THREE.Vector3(0, 0.5, 0)), "PARRY!", neutralDragonSwitch ? "#ffffff" : "#8fe6ff", 1.4);', 'white parry text'),
      ('this.fxp("impactBurst", hitPos, "#ff9f43", 1.65, "clash");',
       'this.fxp("impactBurst", hitPos, neutralDragonSwitch ? "#dedede" : "#ff9f43", 1.65, "clash");', 'gray guardbreak impact'),
      ('this.fxp("impactFrame", "guardbreak", "#ff9f43", 0.85);',
       'this.fxp("impactFrame", "guardbreak", neutralDragonSwitch ? "#dedede" : "#ff9f43", 0.85);', 'gray guardbreak frame'),
      ('this.fxp("sparks", hitPos, "#ffb347", 40, 9);',
       'this.fxp("sparks", hitPos, neutralDragonSwitch ? "#dedede" : "#ffb347", 40, 9);', 'gray guardbreak sparks'),
      ('this.fxp("flash", hitPos, "#ffb34d", 0.5, 0.2, 0.9);',
       'this.fxp("flash", hitPos, neutralDragonSwitch ? "#ffffff" : "#ffb34d", neutralDragonSwitch ? 0.12 : 0.5, 0.2, 0.9);', 'gray guardbreak flash'),
    )
    for old,new,what in changes:
        source=tweak(source,old,new,what,actions)

    # Other frames (colored) obtain their color from glow and stay neutral.
    return source,actions


def fix_hud(source: str)->tuple[str,bool]:
    if 'DRAGON RHYTHM' not in source:
        return source,False
    # Restrict search to the 800 chars before the Zephyr passive icon.
    ix=source.find('/icons/skills/tristaff-passive.webp')
    if ix<0:return source,False
    a=max(0,ix-800)
    chunk=source[a:ix]
    old='border: "1px solid #69dfc5"'
    if old not in chunk:return source,False
    chunk=chunk.replace(old,'border: "1px solid rgba(255,255,255,.45)" /* '+MARK+' */',1)
    return source[:a]+chunk+source[ix:],True


def decoded_assets() -> dict[str,bytes]:
    results={}
    for rel,code in ASSETS.items():
        data=zlib.decompress(base64.b85decode(code))
        if len(data)<80 or data[:4]!=b'RIFF' or data[8:12]!=b'WEBP':
            raise RuntimeError('Invalid embedded WebP: '+rel)
        results['public/icons/'+rel]=data
    return results


def main()->int:
    base=Path(sys.argv[1] if len(sys.argv)>1 else '.').expanduser().resolve()
    print('ZEPHYR V23 — ICONS + NEUTRAL SWITCH FX |',base)
    try:
        required=('src/game/game.ts','src/ui/GameView.tsx','src/game/roster.ts')
        source={}
        for rel in required:
            f=base/rel
            if not f.is_file():raise RuntimeError('Missing '+rel+' — run inside fight-royale/web')
            source[rel]=f.read_text('utf-8-sig')
        if not re.search(r'id\s*:\s*[\'\"]zephyr[\'\"]',source['src/game/roster.ts']):
            raise RuntimeError('Zephyr is not installed in the roster. Install V19/V20/V21 first.')
        # Validate every source change before writing a single byte.
        old_game=source['src/game/game.ts']
        if MARK in old_game:
            new_game=old_game;actions=[]
        else:
            new_game,actions=fix_fx(old_game)
            new_game = '// '+MARK+'\n' + new_game
        old_hud=source['src/ui/GameView.tsx']
        new_hud,changed_hud=fix_hud(old_hud)
        source_edits={}
        if old_game!=new_game:source_edits['src/game/game.ts']=new_game
        if old_hud!=new_hud:source_edits['src/ui/GameView.tsx']=new_hud
        assets=decoded_assets()
        # Do not replace custom icons, including if they're different sizes.
        missing={rel:data for rel,data in assets.items() if not (base/rel).is_file()}
        if not source_edits and not missing:
            print('Already up to date; no files changed.')
            return 0
        stamp=dt.datetime.now().strftime('%Y%m%d-%H%M%S')
        backup=base/'.zephyr-backups'/('v23-'+stamp)
        for rel in source_edits:
            (backup/rel).parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(base/rel,backup/rel)
        created=[]
        try:
            for rel,data in missing.items():
                p=base/rel;p.parent.mkdir(parents=True,exist_ok=True)
                # exclusive create: never overwrite an already-installed custom asset
                with p.open('xb') as f:f.write(data)
                created.append(p)
                print('  icon:',rel)
            for rel,content in source_edits.items():
                (base/rel).write_text(content,encoding='utf-8')
                print('  updated:',rel)
        except Exception:
            for p in created:p.unlink(missing_ok=True)
            for rel in source_edits:
                shutil.copy2(backup/rel,base/rel)
            raise
        if actions:print('  FX repairs:',', '.join(actions))
        if changed_hud:print('  HUD: neutral gray border')
        print('Installed',len(missing),'missing icons. Existing icon files kept unchanged.')
        print('Backup:',backup)
        print('Test: npx tsc --noEmit -p . && npm run dev')
        print('Browser: Ctrl+Shift+R to refresh static assets.')
        return 0
    except Exception as err:
        print('ERROR:',err,file=sys.stderr)
        return 1

if __name__=='__main__':
    raise SystemExit(main())
